# -*- coding: utf-8 -*-
"""读取教材数据，生成同目录的离线交互HTML；依赖 openpyxl。"""
from pathlib import Path
import json
import warnings
import openpyxl

HERE=Path(__file__).resolve().parent
SOURCE=next((p for base in HERE.parents for p in base.glob('《*/第三章*.xlsm')),None)
if SOURCE is None:
    raise FileNotFoundError('未找到教材目录中的第三章 动态图表.xlsm')
# 只读原始数据，绝不保存或修改带宏的工作簿。
with warnings.catch_warnings():
    warnings.filterwarnings('ignore',message='Slicer List extension is not supported.*')
    book=openpyxl.load_workbook(SOURCE,data_only=True,read_only=True)
sheet=book['5 透视表切片器']
def row(r,c1,c2):
    values=[sheet.cell(r,c).value for c in range(c1,c2+1)]
    if any(v is None for v in values):raise ValueError(f'数据缺失：{sheet.title}第{r}行')
    return values
def col(c,r1,r2):
    values=[sheet.cell(r,c).value for r in range(r1,r2+1)]
    if any(v is None for v in values):raise ValueError(f'数据缺失：{sheet.title}第{c}列')
    return values
# 明细表只用于汇总计算，不生成页面，也不把员工明细嵌入HTML。
source=book['5 人力资源明细']
education=col(2,4,8)
departments=['财务','工程','后勤','人力资源','市场拓展','销售','行政']
groups={d:{e:[0,0] for e in education} for d in departments}
count=0
for record in source.iter_rows(min_row=2,values_only=True):
    if all(v is None for v in record):continue
    dept,edu,income=record[2],record[3],record[6]
    if dept not in groups or edu not in groups[dept] or not isinstance(income,(int,float)):
        raise ValueError('人力资源明细含未知部门、学历或无效月收入')
    groups[dept][edu][0]+=income;groups[dept][edu][1]+=1;count+=1
data={'labels':education,'departments':departments,'groups':groups,'initial':['市场拓展']}
assert count==1470
assert all(abs(groups['市场拓展'][e][0]/groups['市场拓展'][e][1]-sheet.cell(i,3).value)<1e-8 for i,e in enumerate(education,4))

book.close()

PAGE = '<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>透视表切片器</title><style>\n:root{color-scheme:dark;--bg:#1a1e43;--ink:#f5f5fa;--muted:#d1d4e8;--blue:#0070c0;--edge:#5e6384;--focus:#f5c353}\n*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--ink);font-family:"Microsoft YaHei","SimHei",sans-serif}body{font-variant-numeric:tabular-nums}::selection{background:#0070c0;color:white}\nmain{max-width:1000px;margin:0 auto;padding:44px 0 24px}h1{font-size:34px;line-height:1.4;margin:0 55px;font-weight:700;letter-spacing:0}button,select,input{font:inherit}button,select{min-height:36px;border:1px solid #a4a6b4;border-radius:2px;padding:5px 13px;background:#f2f2f4;color:#171a31;cursor:pointer}button:hover,select:hover{background:#fff}button[aria-pressed="true"]{background:#0070c0;border-color:#4bb5f4;color:white}button:disabled{opacity:.45;cursor:default}input{accent-color:#0070c0}button:focus-visible,select:focus-visible,input:focus-visible,[tabindex]:focus-visible{outline:3px solid var(--focus);outline-offset:4px}\n.toolbar{display:flex;justify-content:flex-end;align-items:center;gap:12px;flex-wrap:wrap;margin:14px 55px 4px;min-height:40px}.toolbar label{display:inline-flex;gap:7px;align-items:center;font-size:16px;cursor:pointer}.toolbar input{width:16px;height:16px;margin:0}.toolbar fieldset{display:flex;gap:14px;border:0;padding:0;margin:0}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}\n.legend-toolbar{justify-content:flex-start;gap:24px}.legend-toolbar label{padding:7px 12px;font-size:16px;color:white}.legend-toolbar label:nth-of-type(1){background:#0070c0}.legend-toolbar label:nth-of-type(2){background:#e74e69}.legend-toolbar label:nth-of-type(3){background:#ffc000;color:#182040}\n.plot-wrap{width:100%;overflow-x:auto;scrollbar-color:#737aab #1a1e43;scrollbar-width:thin}.plot{display:block;width:100%;height:auto;touch-action:pan-x pan-y}.plot text{font-family:"Microsoft YaHei","SimHei",sans-serif;fill:var(--ink)}.mark{cursor:default;transition:filter .15s}.mark:hover,.mark:focus{filter:brightness(1.12)}.grid{stroke:#b7bed2;stroke-opacity:.20;stroke-width:1;stroke-dasharray:9 5}.axis{stroke:#5e6384;stroke-width:1}\nfooter{font-size:13px;color:var(--muted);margin:15px 50px 0;line-height:1.7}#tip{position:fixed;z-index:5;max-width:300px;padding:10px 13px;background:#f7f8fc;color:#172039;border:1px solid #9ba6cb;border-radius:4px;box-shadow:0 5px 18px #0005;font-size:14px;line-height:1.6;pointer-events:none;white-space:pre-line}#tip[hidden]{display:none}\n.slicer{margin:0 55px 26px;border:1px solid #5e6384;padding:12px;background:#f1f2f7;color:#202439}.slicer-top{display:flex;align-items:center;gap:18px;justify-content:space-between;margin-bottom:12px}.slicer-top label{display:flex;align-items:center;gap:6px;font-size:14px}.slicer-top button{min-height:30px;font-size:13px}.departments{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.departments button{min-height:35px;font-size:15px;text-align:left}.slicer button[aria-pressed="false"]{background:#dce8f7;border-color:#92b4d7;color:#1c3553}.slicer button[aria-pressed="false"]:hover{background:#c7def8}.selection{font-size:14px;color:var(--muted);margin:8px 55px 0;min-height:20px}\n@media(max-width:640px){main{padding-top:24px}h1{font-size:25px;margin:0 22px}.toolbar{margin:16px 22px 5px;gap:9px}.toolbar label{font-size:14px}.legend-toolbar{gap:8px}.legend-toolbar label{padding:6px 8px;font-size:14px}footer{margin:15px 22px;font-size:12px}.slicer{margin:0 22px 20px}.slicer-top{gap:7px;flex-wrap:wrap}.departments{grid-template-columns:repeat(2,1fr)}.selection{margin:8px 22px}.slicer-top strong{margin-right:auto}}\n@media(prefers-reduced-motion:reduce){*{transition:none!important}}\n</style></head>\n<body><main><div class="slicer" role="group" aria-label="部门切片器"><div class="slicer-top"><strong>部门</strong><label><input type="checkbox" id="multi">多选</label><button type="button" id="clear">清除筛选</button></div><div class="departments"><button type="button" data-department="财务" aria-pressed="false">财务</button><button type="button" data-department="工程" aria-pressed="false">工程</button><button type="button" data-department="后勤" aria-pressed="false">后勤</button><button type="button" data-department="人力资源" aria-pressed="false">人力资源</button><button type="button" data-department="市场拓展" aria-pressed="false">市场拓展</button><button type="button" data-department="销售" aria-pressed="false">销售</button><button type="button" data-department="行政" aria-pressed="false">行政</button></div></div><h1 id="chart-title">各学历平均工资情况</h1><p id="selection" class="selection"></p>\n<div class="plot-wrap" tabindex="0" aria-label="图表区域"><svg id="chart" class="plot" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 510" role="group" aria-label="交互图表"></svg></div>\n<footer>*注：数据来源于人力资源管理系统，统计日期截至2022.03.31</footer><p id="status" class="sr-only" aria-live="polite"></p></main>\n<div id="tip" role="tooltip" hidden></div><script id="source-data" type="application/json">__SOURCE_DATA__</script><script>\nconst DATA=JSON.parse(document.getElementById(\'source-data\').textContent);\nconst svg=document.getElementById(\'chart\'), title=document.getElementById(\'chart-title\'), status=document.getElementById(\'status\'), tip=document.getElementById(\'tip\');\nconst BG=\'#1a1e43\', BLUE=\'#0070c0\', PINK=\'#e74e69\', GOLD=\'#ffc000\';\nconst compact=()=>innerWidth<=640;\nfunction fit(){svg.setAttribute(\'viewBox\',`0 0 ${compact()?660:1000} 510`)}\nfit();addEventListener(\'resize\',()=>{fit();update()});\nconst esc=s=>String(s).replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst num=(v,d=0)=>Number(v).toLocaleString(\'en-US\',{useGrouping:false,minimumFractionDigits:d,maximumFractionDigits:d});\nconst pct=v=>num(v*100,0)+\'%\';\nconst exactPct=v=>Number((v*100).toFixed(2))+\'%\';\nfunction attrs(obj){return Object.entries(obj).map(([k,v])=>` ${k}="${esc(v)}"`).join(\'\')}\nfunction txt(x,y,s,size=19,anchor=\'middle\',fill=\'#f5f5fa\',more={}){return `<text${attrs({x,y,\'font-size\':size,\'text-anchor\':anchor,fill,...more})} style="fill:${fill}">${esc(s)}</text>`}\nfunction line(x1,y1,x2,y2,color,width=1,more={}){return `<line${attrs({x1,y1,x2,y2,stroke:color,\'stroke-width\':width,...more})}/>`}\nfunction rect(x,y,w,h,fill,more={}){return `<rect${attrs({x,y,width:w,height:Math.max(0,h),fill,...more})}/>`}\nfunction circle(x,y,r,fill,more={}){return `<circle${attrs({cx:x,cy:y,r,fill,...more})}/>`}\nfunction mark(label,value,extra={}){return {class:\'mark\',tabindex:0,role:\'img\',\'aria-label\':label,\'data-tip\':label,\'data-value\':value,...extra}}\nfunction polar(cx,cy,r,a){return [cx+r*Math.cos(a*Math.PI/180),cy+r*Math.sin(a*Math.PI/180)]}\nfunction ringPath(cx,cy,outer,inner,start,end){\n    const a=polar(cx,cy,outer,start),b=polar(cx,cy,outer,end),c=polar(cx,cy,inner,end),d=polar(cx,cy,inner,start),large=end-start>180?1:0;\n    return `M${a} A${outer},${outer} 0 ${large} 1 ${b} L${c} A${inner},${inner} 0 ${large} 0 ${d} Z`;\n}\nfunction ring(cx,cy,outer,inner,start,end,color,more={}){return `<path${attrs({d:ringPath(cx,cy,outer,inner,start,end),fill:color,...more})}/>`}\nfunction options(el,values,selected){el.innerHTML=values.map(s=>`<option${s===selected?\' selected\':\'\'}>${esc(s)}</option>`).join(\'\')}\nfunction announce(message){status.textContent=message;svg.setAttribute(\'aria-label\',message)}\nfunction defs(){return \'<defs><linearGradient id="bar-gradient" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#0070c0"/><stop offset="1" stop-color="#00b0f0"/></linearGradient></defs>\'}\nlet animation=0,shown=[];\nfunction animate(values,paint){\n    cancelAnimationFrame(animation);tip.hidden=true;\n    const from=shown.length===values.length?[...shown]:[...values];\n    const duration=matchMedia(\'(prefers-reduced-motion: reduce)\').matches?0:320;\n    const start=performance.now();\n    const frame=now=>{let t=duration?Math.min((now-start)/duration,1):1;let ease=1-Math.pow(1-t,3);shown=values.map((v,i)=>from[i]+(v-from[i])*ease);paint(shown,t===1);if(t<1)animation=requestAnimationFrame(frame)};\n    frame(start);\n}\nfunction showTip(el,x,y){\n    tip.textContent=el.dataset.tip;tip.hidden=false;\n    tip.style.left=Math.max(8,Math.min(x+14,innerWidth-tip.offsetWidth-12))+\'px\';\n    tip.style.top=Math.max(8,Math.min(y+12,innerHeight-tip.offsetHeight-12))+\'px\';\n}\nsvg.addEventListener(\'pointermove\',e=>{const el=e.target.closest(\'[data-tip]\');if(el)showTip(el,e.clientX,e.clientY);else tip.hidden=true});\nsvg.addEventListener(\'pointerleave\',()=>tip.hidden=true);\nsvg.addEventListener(\'focusin\',e=>{const el=e.target.closest(\'[data-tip]\');if(el){const b=el.getBoundingClientRect();showTip(el,b.x+b.width/2,b.y)}});\nsvg.addEventListener(\'focusout\',()=>tip.hidden=true);\ndocument.addEventListener(\'keydown\',e=>{if(e.key===\'Escape\')tip.hidden=true});\n\nconst multi=document.getElementById(\'multi\'),selection=document.getElementById(\'selection\');let selected=new Set(DATA.initial);\nconst buttons=[...document.querySelectorAll(\'[data-department]\')];\nfunction update(){\n    buttons.forEach(b=>b.setAttribute(\'aria-pressed\',String(selected.has(b.dataset.department))));\n    const names=DATA.departments.filter(d=>selected.has(d)),counts=[],sums=[];\n    DATA.labels.forEach((e,i)=>{sums[i]=0;counts[i]=0;names.forEach(d=>{sums[i]+=DATA.groups[d][e][0];counts[i]+=DATA.groups[d][e][1]})});\n    const values=sums.map((s,i)=>counts[i]?s/counts[i]:null),maximum=Math.max(10000,Math.ceil(Math.max(0,...values.filter(v=>v!==null))/2500)*2500);\n    selection.textContent=names.length===DATA.departments.length?\'全部部门\':(names.length?names.join(\'、\'):\'未选择部门\');\n    window.chartState={departments:names,labels:DATA.labels,values,counts,sums,maximum};announce(selection.textContent+\' · 各学历平均月收入\');\n    animate(values.map(v=>v??0),vs=>{\n        const base=460,h=405;let s=defs();\n        for(let v=0;v<=maximum;v+=2500){const y=base-v/maximum*h;s+=line(compact()?65:80,y,compact()?610:930,y,\'#b7bed2\',1,{class:\'grid\'})}\n        DATA.labels.forEach((l,i)=>{const x=compact()?115+i*110:165+i*168,y=base-vs[i]/maximum*h;\n            if(values[i]!==null){s+=rect(x-(compact()?22:27),y,compact()?44:54,base-y,\'url(#bar-gradient)\',mark(`${l}\\n平均月收入 ${num(values[i],2)}元\\n${counts[i]}人`,values[i],{\'data-category\':l,\'data-count\':counts[i]}));s+=txt(x,y-20,num(values[i],2),19)}\n            else if(names.length)s+=txt(x,base-25,\'无数据\',18);\n            s+=txt(x,base+35,l,23);\n        });\n        if(!names.length)s+=txt(compact()?330:505,235,\'请选择部门\',24);svg.innerHTML=s;\n    });\n}\nbuttons.forEach(b=>b.addEventListener(\'click\',e=>{const d=b.dataset.department;if(multi.checked||e.ctrlKey||e.metaKey){selected.has(d)?selected.delete(d):selected.add(d)}else selected=new Set([d]);update()}));\ndocument.getElementById(\'clear\').addEventListener(\'click\',()=>{selected=new Set(DATA.departments);update()});\nupdate();\n</script></body></html>'

payload=json.dumps(data,ensure_ascii=False,allow_nan=False).replace('<','\u003c')
output=HERE/(Path(__file__).stem+'.html')
output.write_text(PAGE.replace('__SOURCE_DATA__',payload),encoding='utf-8')
print(output)
